impl Solution {
    pub fn max_compatibility_sum(students: Vec<Vec<i32>>, mentors: Vec<Vec<i32>>) -> i32 {
        let m = students.len();
        let n = students[0].len();

        // Precompute compatibility scores for all student-mentor pairs
        let mut score = vec![vec![0; m]; m];
        for i in 0..m {
            for j in 0..m {
                let mut s = 0;
                for k in 0..n {
                    if students[i][k] == mentors[j][k] {
                        s += 1;
                    }
                }
                score[i][j] = s;
            }
        }

        // Use bitmask dp to assign mentors to students
        // dp[mask] = max compatibility sum for assigning mentors in mask to first count_ones(mask) students
        // We'll assign students in order 0..m-1, and mask represents which mentors are assigned
        let mut dp = vec![0; 1 << m];
        for mask in 0..(1 << m) {
            let student_idx = mask.count_ones() as usize;
            if student_idx == m {
                continue;
            }
            for mentor in 0..m {
                if (mask & (1 << mentor)) == 0 {
                    let next_mask = mask | (1 << mentor);
                    dp[next_mask] = dp[next_mask].max(dp[mask] + score[student_idx][mentor]);
                }
            }
        }

        dp[(1 << m) - 1]
    }
}

